#include "protocol.h"
static void put32(uint8_t *p, uint32_t v) { p[0]=(uint8_t)v; p[1]=(uint8_t)(v>>8); p[2]=(uint8_t)(v>>16); p[3]=(uint8_t)(v>>24); }
static uint32_t get32(const uint8_t *p) { return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24); }
uint16_t dw_crc16(const uint8_t *data, size_t len) { uint16_t crc=0xffffu; for(size_t i=0;i<len;i++){ crc^=(uint16_t)data[i]<<8; for(unsigned b=0;b<8;b++) crc=(crc&0x8000u)?(uint16_t)((crc<<1)^0x1021u):(uint16_t)(crc<<1); } return crc; }
int dw_encode(uint8_t out[DW_FRAME_SIZE], uint8_t kind, uint32_t id, uint32_t seq, int32_t val) { if(!out || (kind!=DW_KIND_INLET && kind!=DW_KIND_RAIN)) return -1; out[0]=DW_VERSION; out[1]=kind; put32(out+2,id); put32(out+6,seq); put32(out+10,(uint32_t)val); uint16_t c=dw_crc16(out,14); out[14]=(uint8_t)c; out[15]=(uint8_t)(c>>8); return 0; }
int dw_decode(const uint8_t *f,size_t n,uint8_t *kind,uint32_t *id,uint32_t *seq,int32_t *val) { if(!f||n!=DW_FRAME_SIZE||!kind||!id||!seq||!val||f[0]!=DW_VERSION||(f[1]!=DW_KIND_INLET&&f[1]!=DW_KIND_RAIN)) return -1; uint16_t c=(uint16_t)f[14]|((uint16_t)f[15]<<8); if(c!=dw_crc16(f,14)) return -2; *kind=f[1]; *id=get32(f+2); *seq=get32(f+6); *val=(int32_t)get32(f+10); return 0; }
